"""v14 visual pipeline integration tests. Uses the shipped standalone HTML, no mock renderer.
Screenshots are actual WebGL output. Controlled placements are reproducible QA scenes.
"""
from pathlib import Path
from playwright.sync_api import sync_playwright
import os,json,time
ROOT=Path(__file__).resolve().parents[1]
os.environ.setdefault('DISPLAY',':99')
results=[]
def check(name,ok,detail=''):
 results.append({'name':name,'passed':bool(ok),'detail':detail});print(('PASS' if ok else 'FAIL'),name,detail,flush=True)
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=False,args=['--no-sandbox','--ignore-gpu-blocklist','--enable-webgl','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 p=b.new_page(viewport={'width':1280,'height':800},device_scale_factor=1)
 errors=[];requests=[]
 p.on('pageerror',lambda e:errors.append(str(e)))
 p.on('console',lambda m:errors.append(m.text) if m.type=='error' else None)
 p.on('request',lambda r:requests.append(r.url) if r.url.startswith(('http://','https://')) else None)
 p.set_content((ROOT/'index.html').read_text(),wait_until='load')
 p.wait_for_function('window.cryptDebug && cryptDebug.renderer.texturesReady===2')
 p.evaluate('cryptDebug.setAuto(false);cryptDebug.setRenderAuto(false)')
 check('v14.1 boot and two embedded material atlases loaded',p.evaluate('cryptDebug.getV14().version==="14.1"&&cryptDebug.renderer.texturesReady===2'))
 p.click('#start');p.evaluate('cryptDebug.game.aiFrozen=true;cryptDebug.game.paused=false;cryptDebug.renderer.scale=.5;cryptDebug.render()')
 check('Arches and carved wall reliefs generated',p.evaluate('cryptDebug.renderer.staticMeta.arches>0&&cryptDebug.renderer.staticMeta.wallReliefs>0'))
 check('Balanced mode: seven draw calls',p.evaluate('cryptDebug.renderer.drawCalls===7'))
 check('All framebuffers complete',p.evaluate('''(()=>{const r=cryptDebug.renderer,g=r.gl;const ok=[r.shadowTarget,r.sceneTarget,...r.blooms].every(t=>{g.bindFramebuffer(g.FRAMEBUFFER,t.fbo);return g.checkFramebufferStatus(g.FRAMEBUFFER)===g.FRAMEBUFFER_COMPLETE});g.bindFramebuffer(g.FRAMEBUFFER,null);return ok})()'''))
 p.evaluate('''window.qaPixels=()=>{cryptDebug.render();const r=cryptDebug.renderer,g=r.gl,a=new Uint8Array(r.canvas.width*r.canvas.height*4);g.readPixels(0,0,r.canvas.width,r.canvas.height,g.RGBA,g.UNSIGNED_BYTE,a);return a};window.qaDiff=(a,b)=>{let sum=0;for(let i=0;i<a.length;i++)if(i%4<3)sum+=Math.abs(a[i]-b[i]);return sum/(a.length*.75)};window.qaMean=a=>{let sum=0;for(let i=0;i<a.length;i++)if(i%4<3)sum+=a[i];return sum/(a.length*.75)};void 0;''')
 d=p.evaluate('''(()=>{const r=cryptDebug.renderer;r.options.shadows=true;const a=qaPixels();r.options.shadows=false;const d=qaDiff(a,qaPixels());r.options.shadows=true;return d})()''');check('Shadow map changes actual image pixels',d>.005,f'mean absolute RGB difference={d:.4f}')
 d=p.evaluate('''(()=>{const r=cryptDebug.renderer;r.options.bump=0;const a=qaPixels();r.options.bump=1;return qaDiff(a,qaPixels())})()''');check('Normal mapping changes actual image pixels',d>.005,f'mean difference={d:.4f}')
 d=p.evaluate('''(()=>{const r=cryptDebug.renderer;r.options.bloom=false;const a=qaPixels();r.options.bloom=true;return qaDiff(a,qaPixels())})()''');check('Bloom changes actual image pixels',d>.005,f'mean difference={d:.4f}')
 vals=p.evaluate('''(()=>{const r=cryptDebug.renderer;r.options.exposure=.7;const a=qaMean(qaPixels());r.options.exposure=1.3;const b=qaMean(qaPixels());r.options.exposure=1;return[a,b]})()''');check('Exposure slider raises mean luminance',vals[1]>vals[0]+1,str(vals))
 p.evaluate('window.qaBefore=JSON.stringify(cryptDebug.game.snapshot());cryptDebug.renderer.setPreset("performance");cryptDebug.render()')
 check('Performance preset disables shadows/bloom and uses three draw calls',p.evaluate('!cryptDebug.renderer.options.shadows&&!cryptDebug.renderer.options.bloom&&cryptDebug.renderer.drawCalls===3'))
 p.evaluate('cryptDebug.renderer.setPreset("cinematic");cryptDebug.render()')
 check('High quality preset allocates 2048 shadow map',p.evaluate('cryptDebug.renderer.shadowTarget.w===2048&&cryptDebug.renderer.gl.getError()===0'))
 check('Graphics changes do not mutate gameplay snapshot',p.evaluate('qaBefore===JSON.stringify(cryptDebug.game.snapshot())'))
 p.evaluate('cryptDebug.renderer.setPreset("balanced");cryptDebug.renderer.scale=.75;cryptDebug.render()')
 check('Resolution scale resizes all scene targets',p.evaluate('cryptDebug.renderer.canvas.width===960&&cryptDebug.renderer.sceneTarget.w===960&&cryptDebug.renderer.blooms[0].w===240'))
 p.evaluate('cryptDebug.renderer.scale=.5;cryptDebug.render()')
 check('Repeated resize releases/recreates valid targets',p.evaluate('cryptDebug.renderer.canvas.width===640&&cryptDebug.renderer.gl.getError()===0'))
 p.keyboard.press('F1')
 p.select_option('#graphicsPreset','performance')
 check('Actual settings dropdown controls renderer',p.evaluate('cryptDebug.renderer.preset==="performance"&&!cryptDebug.renderer.options.shadows'))
 p.locator('#shadowToggle').check()
 check('Shadow checkbox overrides preset at runtime',p.evaluate('cryptDebug.renderer.options.shadows'))
 p.locator('#bloomToggle').check()
 check('Bloom checkbox controls post processing',p.evaluate('cryptDebug.renderer.options.bloom'))
 p.locator('#exposure').evaluate("el=>{el.value='110';el.dispatchEvent(new Event('input',{bubbles:true}))}")
 check('Brightness range updates renderer and UI label',p.evaluate('cryptDebug.renderer.options.exposure===1.1&&document.getElementById("exposureValue").textContent==="110%"'))
 p.select_option('#graphicsPreset','balanced');p.locator('#exposure').evaluate("el=>{el.value='100';el.dispatchEvent(new Event('input',{bubbles:true}))}")
 p.screenshot(path=str(ROOT/'docs/settings.png'))
 p.click('#resume');p.keyboard.press('F2')
 check('F2 hides HUD without pausing or opening debug panel',p.evaluate('document.body.classList.contains("photoMode")&&!cryptDebug.game.paused&&document.getElementById("debug").hidden'))
 p.keyboard.press('F2')
 check('F2 restores HUD',p.evaluate('!document.body.classList.contains("photoMode")'))
 p.keyboard.press('F2');p.evaluate('cryptDebug.start(true);cryptDebug.game.aiFrozen=true;cryptDebug.game.paused=false')
 check('New run resets photo mode',p.evaluate('!document.body.classList.contains("photoMode")'))
 # Validate finite generated model streams for every role, living/dead pose and player weapon.
 result=p.evaluate('''(()=>{const g=cryptDebug.game;g.enemies=[];g.containers=[];g.player.x=31;g.player.z=34;g.player.yaw=0;g.player.pitch=0;let cases=0;for(const type of["skeleton","archer","guardian","warden"]){const e=g.spawnEnemy(type,31,30);for(const dead of[false,true]){e.hp=dead?0:e.maxHp;e.deathTime=.5;const m=CryptScene.scene(g);if(!m.data.every(Number.isFinite)||m.data.length%30)return {ok:false,cases};cases++}g.enemies=[]}for(const id of["rustSword","dagger","axe"]){g.equipment.weapon=CryptCore.makeItem(id);g.mode="melee";const m=CryptScene.scene(g);if(!m.data.every(Number.isFinite)||!(m.worldCount<m.data.length/10))return {ok:false,cases};cases++}return{ok:true,cases}})()''')
 check('All four enemy rigs / death poses / three weapons generate finite mesh data',result['ok'],str(result))
 p.evaluate('''(()=>{const g=cryptDebug.game;g.equipment.weapon=CryptCore.makeItem('rustSword');g.enemies=[];const s=g.spawnEnemy('skeleton',31,30.8);s.yaw=Math.PI;const a=g.spawnEnemy('archer',35.4,27.3);a.yaw=Math.PI;const h=g.spawnEnemy('guardian',27,28);h.yaw=Math.PI;g.player.pitch=-.02;g.player.attack=null;g.mode='melee';g.time=3;cryptDebug.renderer.scale=1;cryptDebug.step(0);document.getElementById('toast').textContent='';cryptDebug.render()})()''')
 p.screenshot(path=str(ROOT/'docs/combat_detail.png'))
 check('All character roles render without WebGL errors',p.evaluate('cryptDebug.renderer.gl.getError()===0'))
 p.evaluate('''(()=>{const g=cryptDebug.game;g.enemies=[];g.boss=g.spawnEnemy('warden',31,30.5);g.boss.hp=270;g.boss.phase=2;g.player.pitch=.14;g.mode='magic';g.time=4;cryptDebug.step(0);document.getElementById('toast').textContent='';cryptDebug.render()})()''')
 p.screenshot(path=str(ROOT/'docs/boss_magic.png'))
 check('Boss and fire spell viewmodel render with post processing',p.evaluate('cryptDebug.renderer.gl.getError()===0&&cryptDebug.game.mode==="magic"'))
 p.evaluate('''(()=>{const g=cryptDebug.game;g.mode='bow';g.player.pitch=0;g.projectiles.push({pos:[30.7,1.6,32],vel:[0,0,-12],owner:'player',power:40,magic:true,life:1});g.effects.push({pos:[31.6,1.5,31.5],life:.28,color:[1,.55,.1]});cryptDebug.render()})()''')
 check('Fireball trails and hit sparks render without errors',p.evaluate('cryptDebug.renderer.gl.getError()===0'))
 check('No runtime JavaScript/WebGL error reports',len(errors)==0,str(errors))
 check('No external HTTP requests',len(requests)==0,str(requests))
 out={'suite':'v14.1 graphics pipeline','browser':b.version,'method':'set_content in Chromium/Xvfb/SwiftShader; real shaders, framebuffers, input and pixels; controlled QA placements','total':len(results),'passed':sum(x['passed'] for x in results),'failed':sum(not x['passed'] for x in results),'results':results,'errors':errors,'externalRequests':requests}
 (ROOT/'tests/graphics_results.json').write_text(json.dumps(out,ensure_ascii=False,indent=2));b.close()
print(json.dumps({k:out[k] for k in ['total','passed','failed']}))
raise SystemExit(1 if out['failed'] else 0)
